__NUXT_JSONP__("/about", (function(a){return {data:[{details:{slug:"en",pageTitle:"What is MLI? | Mentor Language Institute",pageDescription:"Mentor Language Institute was founded in 2002 and is located in two popular areas: Westwood & Hollywood.",section1:{title:"What is MLI?",description:["Mentor Language Institute was founded in 2002 and is located in two popular areas: Westwood & Hollywood. \u003Cbr \u002F\u003EWe help students from all over the world improve their English."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Pay Less for Quality Classes",description:["We value two things: \u003Cb\u003E“Quality of Education”\u003C\u002Fb\u003E and \u003Cb\u003E“Price.”\u003Cb\u003E","English is the global language and a necessary tool for communication with people from around the world. Our hope is that international students acquire English skills to succeed in the world. For this reason, we focus on the quality of classes and low price."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"As of 2020, over 17,000 students have chosen and graduated from MLI.",description:["We offer ESL program (General English Program with 6 skill areas : Grammar\u002FWriting, Reading\u002FVocabulary, and Listening\u002FSpeaking), TOEFL®, IELTS™ (For students who want to prepare to go to college), and TOEIC®.","Many students have also gone on to study at universities or colleges in the U.S. like UCLA, USC and Santa Monica College."],lists:[{link:"\u002Ffeature",image:a,text:"5 reasons People Choose MLI"},{link:"\u002Fcompany",image:a,text:"Company Information"},{link:"\u002Fimage-gallery",image:a,text:"Photo \u002F Video Gallery"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:28.442Z",updatedAt:"2025-05-26T12:06:27.572Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));